// Authored for the SVerity accuracy set.
// The second clock is generated by a board PLL whose operating mode is unspecified.
module top(input logic sclk,dclk,input logic [7:0] src_i,output logic [7:0] out_o);
 logic [7:0] training_q=0;
 always_ff @(posedge sclk) training_q<=src_i;
 always_ff @(posedge dclk) out_o<=training_q;
endmodule
